import React from 'react';
import { Link } from 'gatsby';
import { Helmet } from 'react-helmet';
import type { Theme } from '../types';
import { DARK, LIGHT } from '../data';
import { themeRef } from '../components/scene';
import { usePersistentTheme } from '../hooks/usePersistentTheme';
// import { useVisitCounter } from '../hooks/useVisitCounter';
import loadable from '@loadable/component';

const ThreeCanvas = loadable(
  () =>
    import('../components/scene').then((mod) => ({ default: mod.ThreeCanvas })),
  { ssr: false },
);

export default function NotFoundPage() {
  const [isLight, toggle] = usePersistentTheme();
  //   useVisitCounter();
  const t: Theme = isLight ? LIGHT : DARK;

  themeRef.current = t;

  const mono = 'DM Mono, monospace';

  return (
    <>
      <Helmet>
        <html lang='en' />
        <title>404 · Sanj Di</title>
        <link rel='icon' href='/favicon.ico' />
        <link rel='shortcut icon' href='/favicon.ico' />
        <meta name='robots' content='noindex' />
      </Helmet>

      <div
        style={{
          background: t.bg,
          color: t.text,
          fontFamily: mono,
          fontSize: 14,
          lineHeight: 1.6,
          transition: 'background 0.35s ease, color 0.35s ease',
          minHeight: '100vh',
          position: 'relative',
        }}
      >
        <ThreeCanvas />

        <div style={{ position: 'relative', zIndex: 10, minHeight: '100vh' }}>
          <nav
            style={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              zIndex: 100,
              background: t.navBg,
              backdropFilter: 'blur(14px)',
              WebkitBackdropFilter: 'blur(14px)',
              borderBottom: `1px solid ${t.border}`,
              transition: 'background 0.35s, border-color 0.35s',
            }}
          >
            <div
              className='cv-inner'
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                padding: '18px 48px',
              }}
            >
              <Link
                to='/'
                style={{
                  fontFamily: 'Syne, sans-serif',
                  fontSize: 18,
                  fontWeight: 700,
                  letterSpacing: '-0.02em',
                  color: t.text,
                  textDecoration: 'none',
                }}
              >
                SD<span style={{ color: t.purple }}>.</span>
              </Link>

              <div style={{ display: 'flex', alignItems: 'center', gap: 20 }}>
                <span
                  style={{
                    fontSize: 11,
                    letterSpacing: '0.12em',
                    textTransform: 'uppercase',
                    color: t.text3,
                    fontFamily: mono,
                  }}
                >
                  404 / Not Found
                </span>

                <button
                  onClick={toggle}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 2,
                    background: 'transparent',
                    border: `1px solid ${t.border2}`,
                    borderRadius: 100,
                    padding: '4px 6px',
                    cursor: 'pointer',
                    transition: 'border-color 0.2s',
                  }}
                  title={
                    isLight ? 'Switch to dark mode' : 'Switch to light mode'
                  }
                >
                  <span
                    style={{
                      fontSize: 13,
                      lineHeight: 1,
                      padding: '3px 6px',
                      borderRadius: 100,
                      background: isLight ? t.amberDim : 'transparent',
                      boxShadow: isLight ? `0 0 8px 1px ${t.amber}88` : 'none',
                      filter: isLight ? 'none' : 'grayscale(0.4) opacity(0.4)',
                      transition:
                        'background 0.3s, box-shadow 0.3s, filter 0.3s',
                    }}
                  >
                    ☀️
                  </span>
                  <span
                    style={{
                      fontSize: 13,
                      lineHeight: 1,
                      padding: '3px 6px',
                      borderRadius: 100,
                      background: !isLight ? t.purpleDim : 'transparent',
                      boxShadow: !isLight
                        ? `0 0 8px 1px ${t.purple}88`
                        : 'none',
                      filter: !isLight ? 'none' : 'grayscale(0.4) opacity(0.4)',
                      transition:
                        'background 0.3s, box-shadow 0.3s, filter 0.3s',
                    }}
                  >
                    🌙
                  </span>
                </button>
              </div>
            </div>
          </nav>

          <main
            className='cv-inner'
            style={{
              minHeight: '100vh',
              display: 'flex',
              alignItems: 'center',
              padding: '120px 48px 80px',
            }}
          >
            <section
              style={{
                width: '100%',
                maxWidth: 760,
                padding: '40px 0',
              }}
            >
              <div
                style={{
                  fontSize: 11,
                  letterSpacing: '0.2em',
                  textTransform: 'uppercase',
                  color: t.purple,
                  marginBottom: 20,
                  fontFamily: mono,
                }}
              >
                Page not found
              </div>

              <h1
                style={{
                  fontFamily: 'Syne, sans-serif',
                  fontSize: 'clamp(56px, 10vw, 118px)',
                  fontWeight: 800,
                  lineHeight: 0.9,
                  letterSpacing: '-0.04em',
                  color: t.text,
                  marginBottom: 24,
                }}
              >
                404
                <br />
                <span
                  style={{
                    color: 'transparent',
                    WebkitTextStroke: `1px ${t.heroStroke}`,
                  }}
                >
                  Lost route
                </span>
              </h1>

              <p
                style={{
                  maxWidth: 540,
                  fontSize: 14,
                  color: t.text2,
                  lineHeight: 1.8,
                  marginBottom: 36,
                  fontFamily: mono,
                }}
              >
                The page you requested does not exist, may have moved, or the
                URL is malformed. The rest of the portfolio is intact.
              </p>

              <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
                <Link
                  to='/'
                  style={{
                    fontFamily: mono,
                    fontSize: 12,
                    letterSpacing: '0.08em',
                    padding: '14px 32px',
                    background: t.purple,
                    color: '#fff',
                    borderRadius: 4,
                    textDecoration: 'none',
                    display: 'inline-block',
                  }}
                >
                  Return home
                </Link>
                <a
                  href='mailto:hello@sanjdi.com'
                  style={{
                    fontFamily: mono,
                    fontSize: 12,
                    letterSpacing: '0.08em',
                    padding: '14px 32px',
                    background: 'transparent',
                    color: t.text2,
                    border: `1px solid ${t.border2}`,
                    borderRadius: 4,
                    textDecoration: 'none',
                  }}
                >
                  Report broken link
                </a>
              </div>
            </section>
          </main>

          <footer
            style={{
              borderTop: `1px solid ${t.border}`,
              background: t.bg,
              transition: 'background 0.35s, border-color 0.35s',
            }}
          >
            <div
              className='cv-inner'
              style={{
                padding: '24px 48px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
              }}
            >
              <span
                style={{
                  fontSize: 11,
                  color: t.text3,
                  letterSpacing: '0.04em',
                  fontFamily: mono,
                }}
              >
                © 2026 Sanj Di. All rights reserved.
              </span>
              <span
                style={{
                  fontSize: 11,
                  color: t.text3,
                  letterSpacing: '0.04em',
                  fontFamily: mono,
                }}
              >
                Built with Gatsby.js · Melbourne, AU
              </span>
            </div>
          </footer>
        </div>
      </div>
    </>
  );
}
